#[derive(Debug, Clone)]
pub struct ChangeArgs {
    pub target: FieldRef,
    pub op: OpName,
    pub field: FieldRef,
    pub kind: FieldRef,
    pub source: FieldRef,
}

pub fn dispatch_change(
    repo: &mut impl crate::kernel::Repository<Command>, id: &str, args: ChangeArgs,
) -> crate::kernel::DispatchResult<Command> {
        args.target.check_invariants()?;
        if !["set", "append", "increment", "decrement"].contains(&args.op.value.as_str()) { return Err(crate::kernel::Refusal::InvariantViolation(format!("{}{:?}", "op admits Vocabulary::MutationOp — \"set\", \"append\", \"increment\", \"decrement\" — got ", args.op.value))); }
        args.op.check_invariants()?;
        args.field.check_invariants()?;
        args.kind.check_invariants()?;
        args.source.check_invariants()?;

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Change",
        "Bluebook::Command",
        &args,
        &[
            crate::kernel::GivenSpec { description: "a mutation names a target", expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(Expr::Lookup("target.value"))))))) },
            crate::kernel::GivenSpec { description: "a mutation does something", expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(Expr::Lookup("op.value"))))))) },
        ],
        None,
        |record| {
        record.mutations.push(Change { target: args.target.value.clone(), op: args.op.value.clone(), field: args.field.value.clone(), kind: args.kind.value.clone(), source: args.source.value.clone() });
            Ok(())
        },
        &[

        ],
        &["ChangeAttached"],
        args.to_json(),
    )
}

